@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Geist+Mono:wght@400;500&display=swap");
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
  Airy docs: a light documentation system for developer docs, API references
  and knowledge bases. A white page, faint green-grey neutrals, Inter for prose
  and Geist Mono for code. One deep green carries every action and every
  "you are here" mark: the primary pill, the active sidebar link, the selected
  tab. Everything else is a hairline on white, so long pages stay calm.
*/

:root {
  /* ─── Ground: white page, green-grey ink ─── */
  --background: oklch(1 0 0);
  --foreground: oklch(0.214 0.006 156.7);

  --card: oklch(1 0 0);                          /* cards sit on the page, edged by a hairline */
  --card-foreground: oklch(0.214 0.006 156.7);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.214 0.006 156.7);

  /* ─── Primary: the deep docs green ─── */
  --primary: oklch(0.476 0.11 154.3);
  --primary-foreground: oklch(1 0 0);
  --primary-hover: oklch(0.43 0.1 154.3);
  --primary-active: oklch(0.39 0.092 154.3);
  --primary-text: oklch(0.476 0.11 154.3);       /* the green as text on white: 6.3:1 */
  --primary-wash: oklch(0.476 0.11 154.3 / 0.08); /* active nav rows, selected chips */
  --primary-line: oklch(0.476 0.11 154.3 / 0.32);

  --secondary: oklch(0.97 0.004 157.2);          /* the tray: code-block frames, search, quiet buttons */
  --secondary-foreground: oklch(0.214 0.006 156.7);

  --muted: oklch(0.955 0.004 157.2);             /* tracks and wells, one step below the tray */
  --muted-foreground: oklch(0.552 0.005 157.1);

  --accent: oklch(0.97 0.004 157.2);             /* hover rows */
  --accent-foreground: oklch(0.214 0.006 156.7);

  --destructive: oklch(0.577 0.17 25);
  --destructive-foreground: oklch(1 0 0);

  --success: oklch(0.476 0.11 154.3);
  --success-foreground: oklch(1 0 0);
  --warning: oklch(0.648 0.138 69.8);
  --warning-foreground: oklch(0.214 0.006 156.7);
  --info: oklch(0.562 0.156 259.2);
  --info-foreground: oklch(1 0 0);

  --border: oklch(0.214 0.006 156.7 / 0.1);      /* the hairline: ink at one tenth */
  --input: oklch(0.94 0.004 157.2);              /* a pale well where a part fills with it, or a quiet outline */
  --line-strong: oklch(0.65 0.004 160);          /* field edges, switch tracks, outline buttons: 3.2:1 on white */
  --ring: oklch(0.476 0.11 154.3 / 0.7);         /* 3.3:1 on white */
  --radius: 0.75rem;
  /* Radius by size, stepped from --radius the way the catalog derives it:
     chips, fields and rows, panels, cards, dialogs. */
  --radius-sm: 0.5rem;
  --radius-md: 0.625rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.25rem;

  /* ─── Ink ladder ─── */
  --foreground-secondary: oklch(0.373 0.003 164.9); /* sidebar links, body copy in dense lists */
  --foreground-disabled: oklch(0.72 0.004 160);
  --control: oklch(0.6 0.004 160);               /* unchecked box edges and field hover: 3.9:1 on white */
  --field: oklch(1 0 0);
  --thumb: oklch(1 0 0);
  --scrim: oklch(0.155 0.005 173.5 / 0.4);

  /* ─── Code: a white panel inside a pale tray ─── */
  --code: oklch(1 0 0);
  --code-foreground: oklch(0.214 0.006 156.7);
  --code-inline: oklch(0.955 0.004 157.2 / 0.7);
  --syntax-keyword: oklch(0.52 0.19 330);
  --syntax-string: oklch(0.476 0.11 154.3);
  --syntax-fn: oklch(0.5 0.15 259);
  --syntax-comment: oklch(0.552 0.005 157.1);

  /* ─── Callout tints ─── */
  --success-tint: oklch(0.476 0.11 154.3 / 0.08);
  --success-text: oklch(0.42 0.1 154.3);
  --warning-tint: oklch(0.648 0.138 69.8 / 0.1);
  --warning-text: oklch(0.5 0.11 66);
  --info-tint: oklch(0.562 0.156 259.2 / 0.1);
  --info-text: oklch(0.48 0.15 259.2);
  --destructive-tint: oklch(0.577 0.17 25 / 0.08);
  --destructive-text: oklch(0.5 0.16 25);

  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "Geist Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* ─── Depth: the page is flat. Menus and popovers take a hairline ring, no
     shadow; only dialogs and sheets, which sit on a scrim, cast one. ─── */
  --shadow-xs: 0 0.0625rem 0.125rem oklch(0.155 0.005 173.5 / 0.04);
  --shadow-sm: 0 0.0625rem 0.1875rem oklch(0.155 0.005 173.5 / 0.06);
  --shadow-md: 0 0 0 0 oklch(0 0 0 / 0);               /* floating panels carry their own hairline, no shadow */
  --shadow-lg: 0 0.5rem 1.5rem -0.25rem oklch(0.155 0.005 173.5 / 0.1);
  --shadow-card: none;
  --shadow-menu: 0 0 0 0.0625rem oklch(0.214 0.006 156.7 / 0.12);
  --shadow-overlay: 0 1.5rem 3rem -0.75rem oklch(0.155 0.005 173.5 / 0.18), 0 0 0 0.0625rem oklch(0.214 0.006 156.7 / 0.08);
  --shadow-thumb: 0 0.0625rem 0.1875rem oklch(0.155 0.005 173.5 / 0.16), 0 0 0 0.0625rem oklch(0.214 0.006 156.7 / 0.08);

  --chart-1: oklch(0.476 0.11 154.3);
  --chart-2: oklch(0.705 0.169 153.6);
  --chart-3: oklch(0.562 0.156 259.2);
  --chart-4: oklch(0.648 0.138 69.8);
  --chart-5: oklch(0.552 0.005 157.1);

  /* --- Motion (standard profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

